import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Grade } from '../people/people';
import { dueCents, hundredths, rateOf, type Rate } from '../rates/rates';

/** Where a claim is in its life: DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN -> VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A status change a claim's row offers; the server refuses one its status does not allow. */
export type ClaimStatusChange = 'open' | 'settle' | 'void';

/** A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its number on
 * the sheet (given when it is opened; null while a draft and once voided), and its due fixed when it was
 * settled (two decimals; null while live: until settled, and when its grade had no rate then), and the
 * user who opened it (null until opened; that user may not settle it). */
export type Claim = {
  id: number;
  person: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: number | null;
  settledDue: string | null;
  openedBy: string | null;
};

export const claimsKey = (sheet: string) => ['claims', sheet] as const;

export const claimsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/claims`;

/** Every claim on the sheet, newest first. */
export function useClaims(sheet: string) {
  return useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(claimsPath(sheet)),
  });
}

/** The claims that count toward claimed, due-total and every total: the OPEN and SETTLED ones. */
export function counted(claims: Claim[]): Claim[] {
  return claims.filter((c) => c.status === 'OPEN' || c.status === 'SETTLED');
}

/** The sum of the claims' amounts with two decimals, added in whole cents so no float error shows. */
export function claimed(claims: Claim[]): string {
  const cents = claims.reduce((sum, c) => {
    const [whole, frac = ''] = c.amount.split('.');
    return sum + Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  }, 0);
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

/** A claim's due: the one fixed when it was settled, else its amount at the grade's rate in force on its date. */
export function claimDueCents(claim: Claim, pct: string | undefined): bigint | undefined {
  return claim.settledDue !== null ? hundredths(claim.settledDue) : dueCents(claim.amount, pct);
}


/** A person's due-total: the sum of their counted claims' rounded figures. n/a (undefined) when their grade
 *  has no rate on the sheet's today, unless a settled claim keeps a figure: then the figures there are. */
export function personDueCents(
  claims: Claim[],
  rates: Rate[],
  grade: Grade,
  today: string | undefined,
): bigint | undefined {
  const mine = counted(claims);
  if (rateOf(rates, grade, today) === undefined && !mine.some((c) => c.settledDue !== null)) return undefined;
  return mine.reduce((sum, c) => sum + (claimDueCents(c, rateOf(rates, grade, c.date)) ?? 0n), 0n);
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { peoplePath } from '../people/people';
import type { Grade, Person } from '../people/people';
import { useSheetToday } from '../sheet/sheet';
import { rateOf, showDue, useRates } from '../rates/rates';
import type { Rate } from '../rates/rates';
import { claimDueCents, claimed, claimsKey, claimsPath, counted, personDueCents, useClaims } from './claims';
import type { Claim, ClaimStatusChange } from './claims';

type Draft = { amount: string; date: string; note: string };
const EMPTY: Draft = { amount: '', date: '', note: '' };

function ClaimedHeader() {
  return (
    <>
      <th>Claimed</th>
      <th>Due total</th>
      <th>Claims</th>
    </>
  );
}

const CHANGES: { change: ClaimStatusChange; label: string }[] = [
  { change: 'open', label: 'Open' },
  { change: 'settle', label: 'Settle' },
  { change: 'void', label: 'Void' },
];

// One claim with its status and the buttons that change it. Every button is offered; the server
// refuses a change the claim's status does not allow, and the row shows that error until its next action.
function ClaimRow({ sheet, user, claim, rates, grade, editing, onEdit, onCancel }: {
  sheet: string;
  user: string;
  claim: Claim;
  rates: Rate[];
  grade: Grade;
  editing: boolean;
  onEdit: () => void;
  onCancel: () => void;
}) {
  const queryClient = useQueryClient();
  const status = useMutation({
    mutationFn: (change: ClaimStatusChange) =>
      postJson<Claim[]>(byUser(`${claimsPath(sheet)}/${claim.id}/${change}`, user), {}),
    onSuccess: (updated) => queryClient.setQueryData(claimsKey(sheet), updated),
  });

  const act = useSubmitOnce(status);

  return (
    <li data-testid={`claim-row-${claim.id}`}>
      <span data-testid="claim-amount">{claim.amount}</span>{' '}
      <span data-testid="claim-date">{claim.date}</span>{' '}
      <span data-testid="claim-note">{claim.note}</span>{' '}
      due <span data-testid="claim-due">{showDue(claimDueCents(claim, rateOf(rates, grade, claim.date)))}</span>{' '}
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {claim.number !== null && '#'}
      <span data-testid="claim-number">{claim.number ?? ''}</span>{' '}
      {claim.openedBy !== null && 'opened by '}
      <span data-testid="claim-opened-by">{claim.openedBy ?? ''}</span>{' '}
      {CHANGES.map(({ change, label }) => (
        <button
          key={change}
          type="button"
          data-testid={`claim-${change}`}
          disabled={status.isPending}
          onClick={() => act(change)}
        >
          {label}
        </button>
      ))}{' '}
      <button
        type="button"
        data-testid="claim-edit"
        onClick={() => {
          status.reset();
          onEdit();
        }}
      >
        Edit
      </button>
      {editing && (
        <button type="button" data-testid="claim-cancel" onClick={onCancel}>
          Cancel
        </button>
      )}
      {status.isError && (
        <span data-testid="claim-error" role="alert">
          {' '}A {claim.status} claim cannot be changed that way (the user who opened it cannot settle it).
        </span>
      )}
    </li>
  );
}

// A person's claimed total, then their claims (newest first) under one form that adds a claim or,
// once a claim's editor is opened, edits it. A blank date takes the sheet's today on the server.
function PersonClaims({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const { data: all = [] } = useClaims(sheet);
  const claims = all.filter((c) => c.person === person.id);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const [draft, setDraft] = useState<Draft>(EMPTY);
  const [editing, setEditing] = useState<number | null>(null);

  const save = useMutation({
    mutationFn: ({ id, body }: { id: number | null; body: Draft }) =>
      id === null
        ? postJson<Claim[]>(byUser(`${peoplePath(sheet)}/${person.id}/claims`, user), body)
        : putJson<Claim[]>(byUser(`${claimsPath(sheet)}/${id}`, user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(claimsKey(sheet), updated);
      setDraft(EMPTY);
      setEditing(null);
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const open = (c: Claim) => {
    setEditing(c.id);
    setDraft({ amount: c.amount, date: c.date, note: c.note });
    save.reset();
  };

  const cancel = () => {
    setEditing(null);
    setDraft(EMPTY);
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses an amount that is not 0.00 or more with up to two decimals, or a bad date.
    send({ id: editing, body: draft });
  };

  return (
    <>
      <td data-testid="person-claimed">{claimed(counted(claims))}</td>
      <td data-testid="person-due-total">{showDue(personDueCents(claims, rates, person.grade, today))}</td>
      <td>
        <form onSubmit={submit}>
          <input
            data-testid="claim-form-amount"
            placeholder="amount"
            value={draft.amount}
            onChange={(e) => change({ amount: e.target.value })}
          />{' '}
          <input
            data-testid="claim-form-date"
            placeholder="yyyy-mm-dd"
            value={draft.date}
            onChange={(e) => change({ date: e.target.value })}
          />{' '}
          <input
            data-testid="claim-form-note"
            placeholder="note"
            value={draft.note}
            onChange={(e) => change({ note: e.target.value })}
          />{' '}
          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
            {editing === null ? 'Add claim' : 'Save claim'}
          </button>
          {save.isError && (
            <span data-testid="claim-form-error" role="alert">
              {' '}A claim needs an amount of 0.00 or more with up to two decimals, and a valid date.
            </span>
          )}
        </form>
        <ul>
          {claims.map((c) => (
            <ClaimRow
              key={c.id}
              sheet={sheet}
              user={user}
              claim={c}
              rates={rates}
              grade={person.grade}
              editing={editing === c.id}
              onEdit={() => open(c)}
              onCancel={cancel}
            />
          ))}
        </ul>
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 10, Component: ClaimedHeader }),
  PersonColumns.fill({ order: 10, Component: PersonClaims }),
];
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { usePeople } from '../people/people';
import { useSheetToday } from '../sheet/sheet';
import { twoDecimals, useRates } from '../rates/rates';
import { claimed, counted, personDueCents, useClaims } from './claims';

// The sheet's claimed-total: everyone's counted (OPEN and SETTLED) claims added up; and its due-total: everyone's due-total
// added up, skipping the people whose due-total is n/a.
function ClaimedTotal({ sheet }: { sheet: string; user: string }) {
  const { data: all = [] } = useClaims(sheet);
  const claims = counted(all);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const due = people.reduce((sum, p) => {
    const cents = personDueCents(claims.filter((c) => c.person === p.id), rates, p.grade, today);
    return cents === undefined ? sum : sum + cents;
  }, 0n);
  return (
    <>
      <p>
        Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims)}</strong>
      </p>
      <p>
        Due total: <strong data-testid="rollup-due-total">{twoDecimals(due)}</strong>
      </p>
    </>
  );
}

export const contribution = SheetPanels.fill({ order: 20, Component: ClaimedTotal });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

export type Person = { id: number; name: string; grade: Grade; version: number };

export const peopleKey = (sheet: string) => ['people', sheet] as const;

export const peoplePath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;

/** Everyone on the sheet, in the order they were added. */
export function usePeople(sheet: string) {
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(peoplePath(sheet)),
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { GRADES, peopleKey, peoplePath, usePeople } from './people';
import type { Grade, Person } from './people';

type Draft = { name: string; grade: Grade };
const EMPTY: Draft = { name: '', grade: 'A' };

// The sheet's people: listed in the order they were added, with one form that adds a person or,
// once a person's editor is opened, edits them. The editor remembers the version of the person it loaded;
// when someone else has saved them since, the save is refused and the form shows their current values.
function People({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: people = [] } = usePeople(sheet);
  const [draft, setDraft] = useState<Draft>(EMPTY);
  const [editing, setEditing] = useState<{ id: number; version: number } | null>(null);

  const save = useMutation({
    mutationFn: ({ edit, body }: { edit: { id: number; version: number } | null; body: Draft }) =>
      edit === null
        ? postJson<Person[]>(byUser(peoplePath(sheet), user), body)
        : putJson<Person[]>(byUser(`${peoplePath(sheet)}/${edit.id}`, user), { ...body, version: edit.version }),
    onSuccess: (updated) => {
      queryClient.setQueryData(peopleKey(sheet), updated);
      setDraft(EMPTY);
      setEditing(null);
    },
    onError: async (error, { edit }) => {
      if (edit === null || !(error instanceof HttpError) || error.status !== 412) return;
      // Someone else saved the person: show what is stored now, and edit from that version.
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      const p = queryClient.getQueryData<Person[]>(peopleKey(sheet))?.find((c) => c.id === edit.id);
      if (p) {
        setDraft({ name: p.name, grade: p.grade });
        setEditing({ id: p.id, version: p.version });
      }
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const open = (p: Person) => {
    setEditing({ id: p.id, version: p.version });
    setDraft({ name: p.name, grade: p.grade });
    save.reset();
  };

  const cancel = () => {
    setEditing(null);
    setDraft(EMPTY);
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses an empty name, one already on the sheet, or a save over someone else's;
    // its refusal shows as the form's error.
    send({ edit: editing, body: draft });
  };

  return (
    <section>
      <h2>People</h2>
      <form onSubmit={submit}>
        <label>
          Name{' '}
          <input data-testid="person-form-name" value={draft.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          Grade{' '}
          <select
            data-testid="person-form-grade"
            value={draft.grade}
            onChange={(e) => change({ grade: e.target.value as Grade })}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add person' : 'Save person'}
        </button>
        {editing !== null && (
          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
            Cancel
          </button>
        )}
        {save.isError && (
          <span data-testid="person-form-error" role="alert">
            {' '}
            {save.error instanceof HttpError && save.error.status === 412
              ? 'Someone else saved this person since you opened it; the form now shows their values.'
              : 'A person needs a name not already on the sheet and a grade of A, B or C.'}
          </span>
        )}
      </form>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <PersonColumnHeaders.Slot sheet={sheet} user={user} />
            <th />
          </tr>
        </thead>
        <tbody>
          {people.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <PersonColumns.Slot sheet={sheet} user={user} person={p} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 10, Component: People });
