import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a form tell one refusal from another. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useRef } from 'react';
import type { UseMutationResult } from '@tanstack/react-query';

// Sends a mutation unless one sent this way has not answered yet, so a form submitted twice in quick
// succession (a double click) stores one record. `isPending` only shows on the next render, too late
// for the second click; this guard is a ref, set before the first send returns.
export function useSubmitOnce<V>(mutation: UseMutationResult<unknown, unknown, V, unknown>) {
  const busy = useRef(false);
  return (vars: V) => {
    if (busy.current) return;
    busy.current = true;
    mutation.reset();
    mutation
      .mutateAsync(vars)
      .catch(() => {
        /* a refusal shows through the mutation's own error state */
      })
      .finally(() => {
        busy.current = false;
      });
  };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Sheet = { id: string; today: string };

export const sheetKey = (sheet: string) => ['sheet', sheet] as const;

/** The sheet's settings, its today among them. Every default date and date decision on screen
 *  reads `today` from here, never from the browser's clock. */
export function useSheet(sheet: string) {
  return useQuery({
    queryKey: sheetKey(sheet),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}`),
  });
}

/** The sheet's today (yyyy-MM-dd), or undefined while it loads. */
export function useSheetToday(sheet: string): string | undefined {
  return useSheet(sheet).data?.today;
}
